"""Particles under mutual gravity, stepped on the GPU with wgpu compute shaders."""

import math
import sys

import numpy as np
import wgpu

WORKGROUP = 64

SHADER = """
struct Params {
    count: u32,
    dt: f32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read_write> acc: array<vec2<f32>>;

@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j: u32 = 0u; j < params.count; j = j + 1u) {
        if (j == i) {
            continue;
        }
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        a = a + d / (r2 * sqrt(r2));
    }
    acc[i] = a;
}

@compute @workgroup_size(64)
fn integrate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
"""


def read_input(path):
    with open(path) as f:
        tokens = f.read().split()
    count = int(float(tokens[0]))
    steps = int(float(tokens[1]))
    dt = float(tokens[2])
    data = np.array([float(t) for t in tokens[3 : 3 + 4 * count]], dtype=np.float64)
    data = data.reshape(count, 4)
    return count, steps, dt, data[:, 0:2].copy(), data[:, 2:4].copy()


def simulate(pos, vel, steps, dt):
    """Run `steps` steps on the GPU; return final (pos, vel) as float32 arrays."""
    count = pos.shape[0]
    pos32 = np.ascontiguousarray(pos, dtype=np.float32)
    vel32 = np.ascontiguousarray(vel, dtype=np.float32)
    if steps == 0:
        return pos32, vel32

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    usage = (
        wgpu.BufferUsage.STORAGE
        | wgpu.BufferUsage.COPY_SRC
        | wgpu.BufferUsage.COPY_DST
    )
    params = np.zeros(4, dtype=np.uint32)
    params[0] = count
    params.view(np.float32)[1] = dt
    params_buf = device.create_buffer_with_data(
        data=params, usage=wgpu.BufferUsage.UNIFORM
    )
    pos_buf = device.create_buffer_with_data(data=pos32, usage=usage)
    vel_buf = device.create_buffer_with_data(data=vel32, usage=usage)
    acc_buf = device.create_buffer(size=pos32.nbytes, usage=usage)

    module = device.create_shader_module(code=SHADER)
    entry_types = [wgpu.BufferBindingType.uniform] + [wgpu.BufferBindingType.storage] * 3
    layout = device.create_bind_group_layout(
        entries=[
            {
                "binding": b,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": t},
            }
            for b, t in enumerate(entry_types)
        ]
    )
    bind_group = device.create_bind_group(
        layout=layout,
        entries=[
            {"binding": b, "resource": {"buffer": buf, "offset": 0, "size": buf.size}}
            for b, buf in enumerate([params_buf, pos_buf, vel_buf, acc_buf])
        ],
    )
    pipeline_layout = device.create_pipeline_layout(bind_group_layouts=[layout])
    pipelines = [
        device.create_compute_pipeline(
            layout=pipeline_layout,
            compute={"module": module, "entry_point": name},
        )
        for name in ("accelerate", "integrate")
    ]

    groups = (count + WORKGROUP - 1) // WORKGROUP
    encoder = device.create_command_encoder()
    for _ in range(steps):
        # Separate passes give a barrier: every acceleration is computed from
        # the positions the step started with, before any position moves.
        for pipeline in pipelines:
            compute_pass = encoder.begin_compute_pass()
            compute_pass.set_pipeline(pipeline)
            compute_pass.set_bind_group(0, bind_group)
            compute_pass.dispatch_workgroups(groups, 1, 1)
            compute_pass.end()
    device.queue.submit([encoder.finish()])

    out_pos = np.frombuffer(device.queue.read_buffer(pos_buf), dtype=np.float32)
    out_vel = np.frombuffer(device.queue.read_buffer(vel_buf), dtype=np.float32)
    return out_pos.reshape(count, 2), out_vel.reshape(count, 2)


def summarize(pos, vel):
    pos = pos.astype(np.float64)
    vel = vel.astype(np.float64)
    center = pos.mean(axis=0)
    momentum = vel.sum(axis=0)
    kinetic = float(np.sum(vel * vel) / 2.0)
    spread = math.sqrt(float(np.mean(np.sum((pos - center) ** 2, axis=1))))
    return [
        f"CENTER {center[0]:.6f} {center[1]:.6f}",
        f"MOMENTUM {momentum[0]:.6f} {momentum[1]:.6f}",
        f"KINETIC {kinetic:.6f}",
        f"SPREAD {spread:.6f}",
    ]


def fmt_zero(line):
    # Avoid printing "-0.000000".
    return " ".join("0.000000" if t == "-0.000000" else t for t in line.split())


def main(argv):
    count, steps, dt, pos, vel = read_input(argv[1])
    pos, vel = simulate(pos, vel, steps, dt)
    for line in summarize(pos, vel):
        print(fmt_zero(line))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
